import React, { Component } from 'react';
import { NavLink } from 'react-router-dom';
import classes from './DataOwner.module.css';

class DataOwner extends Component {

    render() {

        return (

            <React.Fragment>

                <div className={classes.DataOwnerDisplay}>
                    <h2> Data Owner Page: </h2>

                    <div className={classes.Options}>

                        <NavLink to="/profile/Forms"
                                 exact
                                 className={classes.Select} > UPLOAD DATASET
                        </NavLink>

                        <NavLink to="/profile/MyDatasets"
                                 exact
                                 className={classes.Select} > MY DATASETS
                        </NavLink>

                        <NavLink to="/profile/MyDeals"
                                 exact
                                 className={classes.Select} > MY DEALS
                        </NavLink>

                    </div>

                </div>

            </React.Fragment>

        );
      }
}

export default DataOwner;
